const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Great Fox Island in the Chesapeake Bay, USA.
    const aoi = ee.Geometry.Polygon([[
        [-75.90, 37.85],
        [-75.85, 37.85],
        [-75.85, 37.88],
        [-75.90, 37.88]
    ]]);
    const date1999 = { start: '1999-06-01', end: '1999-09-30' };
    const date2019 = { start: '2019-06-01', end: '2019-09-30' };
    const scale = 30; // Landsat pixel size

    // 2. Data Acquisition & Processing Functions
    // Function to mask clouds in Landsat Collection 2
    function maskL457(image) {
        const qa = image.select('QA_PIXEL');
        const cloud = qa.bitwiseAnd(1 << 5).or(qa.bitwiseAnd(1 << 7));
        return image.updateMask(cloud.not());
    }

    function maskL8(image) {
        const qa = image.select('QA_PIXEL');
        const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4));
        return image.updateMask(cloud.not());
    }

    // Function to calculate NDWI and derive a land mask
    function getLandMask(image, nirBand, greenBand) {
        const ndwi = image.normalizedDifference([greenBand, nirBand]);
        // Land is typically NDWI <= 0
        return ndwi.lte(0).selfMask();
    }

    // Process a collection for a given year
    function calculateAreaForYear(collection, dateRange, maskFunc, nir, green) {
        let imageColl = collection
            .filterBounds(aoi)
            .filterDate(dateRange.start, dateRange.end)
            .filter(ee.Filter.lt('CLOUD_COVER', 30));

        const size = imageColl.size().getInfo();
        if (size === 0) {
            return { area: null, images: 0, validPixels: null };
        }

        const composite = imageColl.map(maskFunc).median();
        const landMask = getLandMask(composite, nir, green);

        // Count valid (land) pixels after masking
        const pixelCount = landMask.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: aoi,
            scale: scale,
            maxPixels: 1e9
        }).values().get(0).getInfo();

        if (pixelCount === 0 || pixelCount === null) {
             return { area: null, images: size, validPixels: 0 };
        }

        // Calculate area from the land mask
        const areaImage = landMask.multiply(ee.Image.pixelArea());
        const area = areaImage.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: aoi,
            scale: scale,
            maxPixels: 1e9
        }).values().get(0).getInfo();

        return { area: area, images: size, validPixels: pixelCount };
    }

    // 3. Calculation
    // For 1999: Landsat 5
    const l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2');
    const result1999 = calculateAreaForYear(l5, date1999, maskL457, 'SR_B4', 'SR_B2');

    // For 2019: Landsat 8
    const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2');
    const result2019 = calculateAreaForYear(l8, date2019, maskL8, 'SR_B5', 'SR_B3');

    // 4. Validation & Final Answer
    const area1999 = result1999.area;
    const area2019 = result2019.area;

    console.log(`1999 Images Found: ${result1999.images}`);
    console.log(`2019 Images Found: ${result2019.images}`);

    if (result1999.images === 0 || result2019.images === 0) {
        console.log("Could not find images for one or both periods.");
        console.log("C1");
        return;
    }

    if (result1999.validPixels === 0 || result2019.validPixels === 0) {
        console.log("No valid land pixels found after cloud masking for one or both periods.");
        console.log("C2");
        return;
    }

    if (area1999 === null || area2019 === null) {
        console.log("Failed to calculate area for one or both periods.");
        console.log("C3");
        return;
    }

    // Convert area from sq meters to hectares for readability
    const areaHa1999 = area1999 / 10000;
    const areaHa2019 = area2019 / 10000;

    console.log(`1999 Valid Land Pixels: ${result1999.validPixels}`);
    console.log(`2019 Valid Land Pixels: ${result2019.validPixels}`);
    console.log(`1999 Estimated Land Area (ha): ${areaHa1999.toFixed(2)}`);
    console.log(`2019 Estimated Land Area (ha): ${areaHa2019.toFixed(2)}`);

    if (area2019 < area1999) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log("D");
    }
}

initEE();
